    json_encode($efUmf));
$efAntw = Bedarf::antworten((array) Db::one("SELECT * FROM bedarf WHERE customer_id = ? AND status <> 'offen' ORDER BY id DESC LIMIT 1", [$zgK]));
pruefe('die Sprachen sind die Antwort, nicht die je Seite gerechnete Menge',
