    $efPflege[$efBet] = (Bedarf::alsFragebogen($zgK)['pflege'] ?? null) === $efSoll;
}
Db::run('UPDATE bedarf SET antworten = ? WHERE id = ?', [$efAlt, $efBid]);
pruefe('Betreuung: „ja“ → ich pflege, „vielleicht“ → offen, „nein“ → er sagt selbst, wer',
