    Hosting::fortsetzen($hsKas);
}
$hsP4 = Hosting::schritte($hs4)['postfach'];
pruefe('Phase 3: nach drei Versuchen wird es Handarbeit -- der Auftrag schließt trotzdem ab und sagt, was fehlt',
