abschnitt('77. DNS übernehmen, Speicher, Cronjob');

$kbBestand = [
    ['name' => '@', 'typ' => 'A', 'wert' => '93.184.216.34'], ['name' => 'www', 'typ' => 'CNAME', 'wert' => 'altfirma.it'],
    ['name' => '@', 'typ' => 'MX', 'wert' => '10 altfirma-it.mail.protection.outlook.com'],
