    return Db::insert('partner_provisionen', ['partner_id' => $pid, 'customer_id' => $wgKunde, 'payment_id' => $z, 'order_id' => $best,
        'art' => 'website', 'basis_cents' => $cents * 10, 'provision_cents' => $cents, 'status' => 'bereit', 'frei_ab' => date('Y-m-d H:i:s')]);
};

