        Db::insert('partner_provisionen', ['partner_id' => $abP, 'customer_id' => $abK1, 'payment_id' => $z, 'order_id' => $b, 'art' => 'website',
            'basis_cents' => 5000, 'provision_cents' => 500, 'status' => 'wartet', 'frei_ab' => date('Y-m-d H:i:s', strtotime('+14 days'))]);
    }
};
