/* ============================================================================
   Partner: Werbe-Paket und Empfehlungsseite (26.09.2026)
   Uwe: „so, dass der Kunde direkt auf den Partnerlink kommt — egal ob QR,
   Bild, Link oder Knopf“. Geprüft wird genau das: Jede Vorlage in jeder
   Sprache trägt den Link ihres Kanals und eine Werbekennzeichnung, jeder
   Teilen-Knopf trägt den Link weiter. Und: Das Foto kommt ohne EXIF und nur
   als 256er WebP in die Datenbank.
   ============================================================================ */
abschnitt('Partner: Werbe-Paket und Empfehlungsseite');
require_once $wurzel . '/src/PartnerWerbung.php';
$pwId = Partner::anlegen(['name' => 'Sara Werbung', 'email' => 'sara@partner.example', 'status' => 'aktiv', 'code' => 'SARAWERB1', 'firma' => '', 'sprache' => 'it']);
$pwP = Db::one('SELECT * FROM partner WHERE id = ?', [$pwId]);
$pwOhneLink = []; $pwOhneKennz = []; $pwAnzahl = 0;
foreach (['it', 'de', 'en'] as $pwS) {
    foreach (PartnerWerbung::vorlagen($pwP, $pwS) as $pwK => $pwListe) {
        foreach ($pwListe as $pwV) {
            $pwAnzahl++;
            // Das TikTok-Drehbuch zeigt den QR im Video; der Link steht in der Beschreibung daneben.
            if (!str_contains($pwV['text'], '/p/SARAWERB1/' . $pwK) && $pwV['id'] !== 'tiktok_skript') { $pwOhneLink[] = $pwS . ':' . $pwV['id']; }
            if (!preg_match('~#(adv|Werbung|ad)\b|partner|collaboro~ui', $pwV['text']) && $pwV['id'] !== 'tiktok_skript') { $pwOhneKennz[] = $pwS . ':' . $pwV['id']; }
        }
    }
}
pruefe('Werbe-Paket: jede Vorlage in jeder Sprache trägt den Link ihres Kanals', $pwAnzahl >= 39 && $pwOhneLink === [], implode(', ', $pwOhneLink) . " ($pwAnzahl)");
pruefe('Werbe-Paket: jede Vorlage sagt, dass es Werbung bzw. eine Partnerschaft ist', $pwOhneKennz === [], implode(', ', $pwOhneKennz));
pruefe('Werbe-Paket: keine Vorlage mit übriggebliebenem Platzhalter', !preg_match('~\{(link|name)\}~', json_encode(PartnerWerbung::vorlagen($pwP, 'de'), JSON_UNESCAPED_UNICODE)));
$pwWa = PartnerWerbung::vorlagen($pwP, 'de')['whatsapp'][0]['teilen'];
$pwMail = PartnerWerbung::vorlagen($pwP, 'de')['email'][0]['teilen'];
pruefe('Teilen-Knöpfe tragen den Kanal-Link weiter (WhatsApp, E-Mail mit Betreff), Instagram teilt das Handy selbst',
    str_starts_with((string) $pwWa, 'https://wa.me/?text=') && str_contains(rawurldecode((string) $pwWa), '/p/SARAWERB1/whatsapp')
    && str_starts_with((string) $pwMail, 'mailto:?subject=') && str_contains(rawurldecode((string) $pwMail), '/p/SARAWERB1/email')
    && PartnerWerbung::vorlagen($pwP, 'de')['instagram'][0]['teilen'] === null);
foreach (array_merge(PartnerWerbung::KANAELE, PartnerWerbung::WERKZEUGE) as $pwK) {
    if (Partner::kanal($pwK) !== $pwK) { pruefe('Kanalname passt zu p.php: ' . $pwK, false); }
}
pruefe('Alle Kanalnamen gehen durch Partner::kanal() — kein Link, den p.php nicht zählt', true);
$pwSig = PartnerWerbung::signatur($pwP, 'de'); $pwKn = PartnerWerbung::websiteKnopf($pwP, 'de');
pruefe('Signatur und Website-Knopf: eigener Kanal-Link, nur Inline-Stil, kein Skript',
    str_contains($pwSig, '/p/SARAWERB1/signatur') && str_contains($pwKn, '/p/SARAWERB1/website')
    && !preg_match('~<script|<style|class=~i', $pwSig . $pwKn));

// Auswertung
Db::run("INSERT INTO partner_klicks (partner_id, tag, anzahl) VALUES (?, CURDATE(), 12)", [$pwId]);
Db::run("INSERT INTO partner_kanal_klicks (partner_id, kanal, tag, anzahl) VALUES (?, 'instagram', CURDATE(), 8), (?, 'whatsapp', CURDATE(), 3)", [$pwId, $pwId]);
$pwK1 = Events::kundeFinden(['name' => 'Werbung Eins', 'email' => 'werbung-eins@esempio.example']);
$pwK2 = Events::kundeFinden(['name' => 'Werbung Zwei', 'email' => 'werbung-zwei@esempio.example']);
Db::run("INSERT INTO partner_zuordnungen (customer_id, partner_id, kanal) VALUES (?, ?, 'instagram'), (?, ?, 'instagram')", [$pwK1, $pwId, $pwK2, $pwId]);
Db::run("INSERT INTO partner_provisionen (partner_id, customer_id, payment_id, art, basis_cents, provision_cents, status, frei_ab)
         VALUES (?, ?, 990101, 'website', 100000, 10000, 'wartet', NOW()), (?, ?, 990102, 'website', 50000, 5000, 'storniert', NOW())", [$pwId, $pwK1, $pwId, $pwK2]);
$pwA = PartnerWerbung::auswertung($pwId);
$pwIg = array_values(array_filter($pwA['zeilen'], static fn($z) => $z['kanal'] === 'instagram'))[0] ?? [];
$pwHaupt = array_values(array_filter($pwA['zeilen'], static fn($z) => $z['kanal'] === ''))[0] ?? [];
pruefe('Was wirkt: Instagram 8 Klicks, 2 Kunden, 1 Verkauf (stornierte Provision zählt nicht), 100 € Provision',
    ($pwIg['klicks'] ?? 0) === 8 && ($pwIg['kunden'] ?? 0) === 2 && ($pwIg['verkaeufe'] ?? 0) === 1 && ($pwIg['provision'] ?? 0) === 10000, json_encode($pwIg));
pruefe('Was wirkt: Klicks ohne Kanal stehen als Hauptlink (12 − 11 = 1), bester Kanal ist Instagram',
    ($pwHaupt['klicks'] ?? 0) === 1 && $pwA['bester'] === 'instagram', json_encode([$pwHaupt, $pwA['bester']]));
Db::run("INSERT INTO partner_kanal_klicks (partner_id, kanal, tag, anzahl) VALUES (?, 'tiktok', CURDATE(), 5)", [$pnP]);
pruefe('Was wirkt: nur Klicks, keine Kunden über einen Kanal → kein „bester Kanal“', PartnerWerbung::auswertung($pnP)['bester'] === null);

// Empfehlungsseite: Satz und Foto
pruefe('Satz: ohne Adressen, höchstens 200 Zeichen, leer entfernt',
    PartnerWerbung::satzSpeichern($pwId, 'Mehr auf www.beispiel.it') === 'satz_link'
    && PartnerWerbung::satzSpeichern($pwId, str_repeat('a', 201)) === 'satz_lang'
    && PartnerWerbung::satzSpeichern($pwId, "  Seriös <b>und</b>\n schnell.  ") === 'ok'
    && (string) Db::wert('SELECT profil_satz FROM partner WHERE id = ?', [$pwId], '') === 'Seriös und schnell.');
$pwDatei = tempnam(sys_get_temp_dir(), 'pwfoto');
$pwBild = imagecreatetruecolor(900, 600); imagefill($pwBild, 0, 0, imagecolorallocate($pwBild, 200, 120, 60)); imagejpeg($pwBild, $pwDatei, 85); imagedestroy($pwBild);
$pwErg = PartnerWerbung::fotoSpeichern($pwId, $pwDatei, (int) filesize($pwDatei));
$pwBlob = (string) Db::wert('SELECT foto FROM partner WHERE id = ?', [$pwId], '');
$pwMass = $pwBlob !== '' ? getimagesizefromstring($pwBlob) : false;
pruefe('Foto: quadratisch 256 px als WebP gespeichert, das Original nicht', $pwErg === 'ok' && $pwMass && $pwMass[0] === 256 && $pwMass[1] === 256 && $pwMass['mime'] === 'image/webp');
file_put_contents($pwDatei, '<?php echo 1;');
pruefe('Foto: keine Bilddatei → abgelehnt, zu groß → abgelehnt',
    PartnerWerbung::fotoSpeichern($pwId, $pwDatei, 20) === 'foto_art' && PartnerWerbung::fotoSpeichern($pwId, $pwDatei, PartnerWerbung::FOTO_MAX_BYTE + 1) === 'foto_gross');
@unlink($pwDatei);
$pwP = Db::one('SELECT * FROM partner WHERE id = ?', [$pwId]);
pruefe('Fotoadresse mit Versionsanhang (neues Foto, neue Adresse)', (string) PartnerWerbung::fotoAdresse($pwP) !== '' && str_contains((string) PartnerWerbung::fotoAdresse($pwP), '&v='));
Partner::loeschen($pwId);
pruefe('Partner gelöscht (mit Belegen): Foto und Satz gehen mit',
    (int) Db::wert('SELECT COUNT(*) FROM partner WHERE id = ? AND (foto IS NOT NULL OR profil_satz IS NOT NULL)', [$pwId], 1) === 0);
$pwPs = (string) file_get_contents($wurzel . '/../p.php');
pruefe('p.php liefert das Foto nur für aktive Partner und zeigt Foto und Satz auf der Landeseite',
    str_contains($pwPs, "status = 'aktiv' AND foto IS NOT NULL") && str_contains($pwPs, 'PartnerWerbung::fotoAdresse($p)') && str_contains($pwPs, '<blockquote>'));
pruefe('Vecom kann Foto und Satz in der Partnerakte entfernen',
    str_contains((string) file_get_contents($wurzel . '/views/partner_akte.php'), 'value="partner_profil_weg"')
    && str_contains((string) file_get_contents($wurzel . '/index.php'), "case 'partner_profil_weg':"));
pruefe('[hidden] gewinnt gegen .knopf (sonst stehen „Zum Startbildschirm“ und leere Teilen-Knöpfe sichtbar da)',
    str_contains((string) file_get_contents($wurzel . '/../assets/css/kunde.css'), '[hidden] { display: none !important; }'));

/* ============================================================================
   Partner: Bilder, Druck und Kurzvideo (26.09.2026)
   Gezeichnet wird im Browser des Partners -- geprüft wird hier, dass jede
   Druckseite den Kanal-Link als QR trägt, dass nur die bekannten Druckarten
   ausgeliefert werden und dass das Skript nichts an fremde Server schickt.
   ============================================================================ */
abschnitt('Partner: Bilder, Druck und Kurzvideo');
require_once $wurzel . '/src/QrBild.php';
$pmId = Partner::anlegen(['name' => 'Nino Druck', 'email' => 'nino@partner.example', 'status' => 'aktiv', 'code' => 'NINODRUCK', 'firma' => 'Tipografia Nino', 'sprache' => 'it']);
$pmP = Db::one('SELECT * FROM partner WHERE id = ?', [$pmId]);
$pmSeiten = [];
foreach (['visitenkarten' => 'karte', 'flyer' => 'flyer', 'aufsteller' => 'flyer', 'aufkleber' => 'flyer'] as $pmArt => $pmKanal) {
    $_GET['druck'] = $pmArt; if ($pmArt === 'aufkleber') { $_GET['hell'] = '1'; }
    $p = $pmP; $sprache = 'it'; $h = static fn(?string $s): string => htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8');
    $T = static fn(string $k): string => Texte::h(Texte::PARTNER[$k] ?? [], 'it');
    ob_start(); require $wurzel . '/views/partner_druck.php'; $pmHtml = (string) ob_get_clean();
    $pmSeiten[$pmArt] = ['html' => $pmHtml, 'kanal' => $pmKanal];
}
unset($_GET['druck'], $_GET['hell']);
$pmZaehl = ['visitenkarten' => 10, 'flyer' => 1, 'aufsteller' => 2, 'aufkleber' => 12];
$pmFalsch = [];
foreach ($pmSeiten as $pmArt => $pmS) {
    if (substr_count($pmS['html'], '<svg') !== $pmZaehl[$pmArt]) { $pmFalsch[] = $pmArt . ': ' . substr_count($pmS['html'], '<svg') . ' QR'; }
    if (!str_contains($pmS['html'], 'NINODRUCK')) { $pmFalsch[] = $pmArt . ': ohne Code'; }
}
pruefe('Druck-Paket: jede Druckart mit der richtigen Zahl QR-Codes und der Adresse des Partners', $pmFalsch === [], implode(', ', $pmFalsch));
pruefe('Druck-Paket: Visitenkarte zählt als „karte“, Flyer als „flyer“ (QR trägt den Kanal-Link)',
    QrBild::svg(PartnerWerbung::link($pmP, 'karte')) === QrBild::svg(Partner::link($pmP) . '/karte')
    && str_contains($pmSeiten['visitenkarten']['html'], QrBild::svg(PartnerWerbung::link($pmP, 'karte'), 200, 1))
    && str_contains($pmSeiten['flyer']['html'], QrBild::svg(PartnerWerbung::link($pmP, 'flyer'), 200, 1)));
pruefe('Druck-Paket: helle Fassung schaltet die Farben um, Flyer trägt die Werbekennzeichnung',
    str_contains($pmSeiten['aufkleber']['html'], '--g:#ffffff') && !str_contains($pmSeiten['flyer']['html'], '--g:#ffffff')
    && str_contains($pmSeiten['flyer']['html'], 'class="werbung"'));
$pmPs = (string) file_get_contents($wurzel . '/../partner.php');
pruefe('Druck-Paket: nur die vier bekannten Druckarten, nur mit Partner-Schlüssel',
    str_contains($pmPs, "if (\$p && in_array((string) (\$_GET['druck'] ?? ''), ['visitenkarten', 'flyer', 'aufsteller', 'aufkleber'], true))"));
$pmJs = (string) file_get_contents($wurzel . '/../assets/js/partner-medien.js');
pruefe('Bilder und Video: im Browser gezeichnet, kein fetch, keine fremde Adresse im Skript',
    !preg_match('~fetch\(|XMLHttpRequest|https?://~', $pmJs) && str_contains($pmJs, 'D.links.bild') && str_contains($pmJs, 'D.links.video'));
pruefe('Kurzvideo: MP4 (H.264) bevorzugt, WebM nur als Rückfall mit Hinweis',
    strpos($pmJs, "'video/mp4;codecs=avc1.42E01E'") < strpos($pmJs, "'video/webm") && str_contains($pmJs, 'D.t.video_webm'));
$pmTexte = true;
foreach (Texte::PARTNER_MEDIEN['motive'] as $pmM) { foreach (['name', 'titel', 'unter'] as $pmF) { foreach (['it', 'de', 'en'] as $pmL) { $pmTexte = $pmTexte && trim((string) ($pmM[$pmF][$pmL] ?? '')) !== ''; } } }
pruefe('Motive für Bilder und Video in allen drei Sprachen', $pmTexte && count(Texte::PARTNER_MEDIEN['motive']) === 6);   // 28.09.2026: + Praxen & Studios (Branchen-Pakete)

/* ============================================================================
   Partner: Kunden finden — Schnellcheck, Firmen-Finder, Vorstellung,
   Wochen-Impuls (26.09.2026)
   Die wichtigsten Zusagen: Der Schnellcheck ruft nie eine private Adresse ab
   (auch nicht über einen Namen, der dorthin zeigt); eine reservierte Firma
   sieht kein anderer Partner, und Vecoms eigene Akquise lässt sie in Ruhe;
   der Firmen-Finder gibt keine Telefonnummern oder E-Mails heraus.
   ============================================================================ */
abschnitt('Partner: Kunden finden (Schnellcheck, Firmen-Finder, Vorstellung, Impuls)');
require_once $wurzel . '/src/PartnerCheck.php';
require_once $wurzel . '/src/PartnerRecherche.php';
require_once $wurzel . '/src/AkquiseGate.php';
pruefe('Schnellcheck: nur echte Website-Adressen (keine IP, kein localhost, kein fremder Port, keine Zugangsdaten)',
    PartnerCheck::adresse('trattoria-rossi.it') === 'https://trattoria-rossi.it/'
    && PartnerCheck::adresse('http://127.0.0.1/') === null && PartnerCheck::adresse('localhost') === null
    && PartnerCheck::adresse('https://beispiel.it:8443/') === null && PartnerCheck::adresse('https://a:b@beispiel.it/') === null
    && PartnerCheck::adresse('ftp://beispiel.it') === null && PartnerCheck::adresse('https://[::1]/') === null);
PartnerCheck::$aufloeser = static fn(string $host): array => $host === 'intern.example' ? ['10.0.0.7'] : ['93.184.215.14'];
pruefe('Schnellcheck: ein Name, der auf eine private Adresse zeigt, wird nicht abgerufen',
    PartnerCheck::oeffentlicheIps('intern.example') === [] && PartnerCheck::holen('https://intern.example/')['fehler'] === 'nicht_oeffentlich'
    && PartnerCheck::pruefen('intern.example')['fehler'] === 'adresse');
PartnerCheck::$holer = static fn(string $url): array => ['ok' => true, 'status' => 200, 'ms' => 4200, 'url' => 'http://alt.example/', 'ssl_tage' => null, 'fehler' => '',
    'inhalt' => '<html><head><title>Trattoria Alt</title></head><body><p>&copy; 2016 Trattoria</p></body></html>'];
$prE = PartnerCheck::pruefen('alt.example');
$prSt = array_column($prE['punkte'], 'stand', 'was');
pruefe('Schnellcheck: alte Seite — langsam, ohne https, ohne Handy-Ansicht, © 2016 veraltet, Titel ohne Beschreibung',
    $prSt === ['tempo' => 'schlecht', 'sicher' => 'schlecht', 'handy' => 'schlecht', 'google' => 'hinweis', 'aktuell' => 'schlecht', 'teilen' => 'hinweis',
               'rechtlich' => 'schlecht', 'telefon' => 'schlecht', 'adresse' => 'hinweis', 'bilder' => 'gut', 'alt' => 'gut', 'zeiten' => 'hinweis'], json_encode($prSt));
PartnerCheck::$holer = static fn(string $url): array => ['ok' => true, 'status' => 200, 'ms' => 600, 'url' => 'https://neu.example/', 'ssl_tage' => 80, 'fehler' => '',
    'inhalt' => '<html><head><title>Hotel Neu</title><meta name="viewport" content="width=device-width"><meta name="description" content="Das schöne Hotel am Meer in Cefalù."><meta property="og:image" content="x.jpg"><script type="application/ld+json">{"@type":"Hotel","openingHours":"Mo-Su 00:00-23:59","address":{"@type":"PostalAddress"}}</script></head><body><a href="tel:+390921123456">0921 123456</a> <img src="a.webp" alt="Terrasse mit Meerblick"> Impressum · Datenschutz © 2025–' . date('Y') . '</body></html>'];
$prSt2 = array_column(PartnerCheck::pruefen('neu.example')['punkte'], 'stand', 'was');
pruefe('Schnellcheck: gepflegte Seite — alle zwölf Punkte grün', count($prSt2) === 12 && count(array_filter($prSt2, static fn($s) => $s === 'gut')) === 12, json_encode($prSt2));
$prOhne = [];
foreach (Texte::PARTNER_CHECK['punkte'] as $prK => $prT) { foreach ($prT as $prStand => $prSatz) { foreach (['it', 'de', 'en'] as $prL) { if (trim((string) ($prSatz[$prL] ?? '')) === '') { $prOhne[] = "$prK.$prStand.$prL"; } } } }
pruefe('Schnellcheck: jeder Satz des Berichts in allen drei Sprachen', $prOhne === [], implode(', ', $prOhne));
$prPid = Partner::anlegen(['name' => 'Rita Recherche', 'email' => 'rita@partner.example', 'status' => 'aktiv', 'code' => 'RITAFIND1', 'firma' => '', 'sprache' => 'de']);
$prPid2 = Partner::anlegen(['name' => 'Otto Anders', 'email' => 'otto@partner.example', 'status' => 'aktiv', 'code' => 'OTTOFIND1', 'firma' => '', 'sprache' => 'de']);
$prA = PartnerCheck::anlegen($prPid, 'alt.example');
pruefe('Schnellcheck: Bericht mit Schlüssel angelegt, Adresse check.php?t=…', $prA['ok'] && preg_match('~/check\.php\?t=[0-9a-f]{32}$~', PartnerCheck::link($prA['token'])) === 1);
for ($i = 0; $i < PartnerCheck::JE_TAG; $i++) { PartnerCheck::anlegen($prPid, 'alt.example'); }
pruefe('Schnellcheck: höchstens ' . PartnerCheck::JE_TAG . ' am Tag je Partner', PartnerCheck::anlegen($prPid, 'alt.example')['grund'] === 'ck_genug');
PartnerCheck::$holer = null; PartnerCheck::$aufloeser = null;
$prChk = (string) file_get_contents($wurzel . '/../check.php');
pruefe('Bericht (check.php): ohne Skript, nie im Index, Knopf auf den Kanal-Link des Partners',
    !preg_match('~<script~i', $prChk) && str_contains($prChk, "default-src 'none'") && str_contains($prChk, 'noindex') && str_contains($prChk, "PartnerWerbung::link(\$p, 'check')"));

// Firmen-Finder und Reservierung
$prF = static fn(string $k, string $n, ?string $url, ?int $score, string $ort = 'Cefalù'): int => (int) Db::insert('akq_firmen', [
