    AkquiseFolge::vorlagenAnlegen() === 15 && (int) Db::wert("SELECT COUNT(*) FROM akq_folge_vorlagen WHERE status = 'entwurf'", [], 0) === 15
    && AkquiseFolge::vorlagenAnlegen() === 0);
