    && count(array_filter(PartnerSeite::ARBEITEN, static fn($a) => str_starts_with((string) PartnerSeite::arbeitUrl($a), 'https://'))) === count(PartnerSeite::ARBEITEN)
    && PartnerSeite::arbeitUrl('trendonix') === 'https://www.trendonix-buecher.de/' && PartnerSeite::arbeitUrl('jonika') === 'https://www.jonika-venturis.com/'
    && PartnerSeite::arbeitUrl('drehesum') === 'https://www.dreh-es-um.de/' && PartnerSeite::arbeitUrl('../x') === null
    && count(array_filter(PartnerSeite::ARBEITEN, static fn($a) => is_file($wurzel . '/../assets/img/arbeiten/' . $a . '/an.webp'))) === count(PartnerSeite::ARBEITEN));
Db::run('UPDATE partner SET seite_json = ? WHERE id = ?', [json_encode(['stand' => PartnerSeite::STAND, 'reihenfolge' => ['<script>', 'faq', 'faq'], 'arbeiten' => ['../x', 'jonika', 'mensaena', 'cavaleri', 'trendonix'], 'knopf' => 'boese']), $lsP]);
$lsG2 = PartnerSeite::gestaltung(Db::one('SELECT * FROM partner WHERE id = ?', [$lsP]));
pruefe('Gestaltung: Unbekanntes fällt weg, jeder Abschnitt genau einmal, höchstens drei Arbeiten',
    $lsG2['reihenfolge'][0] === 'faq' && count($lsG2['reihenfolge']) === count(array_unique($lsG2['reihenfolge'])) && count($lsG2['reihenfolge']) === count(PartnerSeite::BAUSTEINE)
    && $lsG2['arbeiten'] === ['jonika', 'mensaena', 'cavaleri'] && $lsG2['knopf'] === 'loslegen');
pruefe('Die drei Wege führen in die Sprache der Seite; unbekannt führt nirgends hin',
    PartnerSeite::wegZiel('check', 'de') === '/website-check.php?lang=de' && PartnerSeite::wegZiel('preis', 'en') === '/bedarf.php?lang=en'
    && PartnerSeite::wegZiel('termin', 'it') === '/termin.php?lang=it' && PartnerSeite::wegZiel('//boese.example', 'it') === null
    && in_array('check', PartnerSeite::wege(), true) && in_array('preis', PartnerSeite::wege(), true));

/* Trichter */
Partner::klick($lsP); Partner::klick($lsP); Partner::klick($lsP); Partner::klick($lsP);
Partner::ereignis($lsP, 'preis'); Partner::ereignis($lsP, 'wa');
$lsT = Partner::trichter($lsP, 7);
pruefe('Trichter: Besuche, Anfragen je Weg (Preisrechner zählt nicht als Anfrage), Kunden',
    $lsT['besuche'] === 4 && $lsT['wege']['email'] === 2 && $lsT['wege']['rueckruf'] === 1 && $lsT['wege']['check'] === 1 && $lsT['wege']['wa'] === 1
    && $lsT['wege']['preis'] === 1 && $lsT['anfragen'] === 5 && $lsT['kunden'] >= 2 && Partner::trichter($lsP, 12345)['tage'] === 30, json_encode($lsT));

/* Werbe-Einwilligung vom Formular der Seite */
$lsPa = Db::one('SELECT * FROM partner WHERE id = ?', [$lsP]);
$lsMails = (int) Db::wert("SELECT COUNT(*) FROM mails WHERE anlass = 'akquise_einwilligung'", [], 0);
pruefe('Werbe-Häkchen ohne Betriebsnamen: keine Bestätigungsmail', PartnerSeite::werbungAnfragen($lsPa, 'ohne@betrieb-ls.example', ' ', '', 'de') === 'betrieb'
    && (int) Db::wert("SELECT COUNT(*) FROM mails WHERE anlass = 'akquise_einwilligung'", [], 0) === $lsMails);
pruefe('Werbe-Häkchen: Betrieb in der Akquise (Quelle partnerseite:CODE), nur die Bestätigungsmail, noch KEINE Erlaubnis',
    PartnerSeite::werbungAnfragen($lsPa, 'titolare@bar-ls.example', 'Bar Lara', 'bar-lara.example', 'it') === 'ok'
    && ($lsWf = Db::one("SELECT * FROM akq_firmen WHERE quelle = 'partnerseite:LARALS01'")) !== null
    && Db::wert("SELECT quelle FROM akq_einwilligungen WHERE firma_id = ? AND status = 'angefragt'", [(int) $lsWf['id']], '') === 'partner'
    && (int) Db::wert("SELECT COUNT(*) FROM mails WHERE anlass = 'akquise_einwilligung'", [], 0) === $lsMails + 1
    && trim((string) ($lsWf['einwilligung'] ?? '')) === '' && AkquiseGate::pruefen($lsWf, 'email')['status'] !== AkquiseGate::ERLAUBT);

/* Vorschaubild */
$lsOg = PartnerSeite::ogBild($lsPa, PartnerSeite::gestaltung($lsPa), 'de', 'Websites für Betriebe in Sizilien', 'Empfohlen von Studio Lara');
$lsOgI = $lsOg !== null ? getimagesizefromstring($lsOg) : false;
pruefe('Link-Vorschau: JPEG 1200×630 (auch ohne Foto und Titelbild)', $lsOgI !== false && $lsOgI[0] === 1200 && $lsOgI[1] === 630 && $lsOgI[2] === IMAGETYPE_JPEG);
pruefe('Link-Vorschau: die Adresse ändert sich, wenn sich die Seite ändert', PartnerSeite::ogAdresse($lsPa, PartnerSeite::gestaltung($lsPa), 'de')
    !== PartnerSeite::ogAdresse(['seite_am' => '2030-01-01 00:00:00'] + $lsPa, PartnerSeite::gestaltung($lsPa), 'de'));

/* Die Seite selbst */
$lsLp = (string) file_get_contents($wurzel . '/../p.php');
pruefe('Landeseite: Vorschau-Tags, Sicherheits-Header, Skript nur aus eigener Datei, kein oninput mehr',
    str_contains($lsLp, 'property="og:image"') && str_contains($lsLp, "script-src 'self'") && str_contains($lsLp, "frame-ancestors 'self'")
    && !preg_match('~<script>~', $lsLp) && !str_contains($lsLp, 'oninput=') && is_file($wurzel . '/../assets/js/partnerseite.js'));
pruefe('Landeseite: Datenschutz an beiden Formularen, Werbe-Häkchen freiwillig, Zählen des Formulars, mitlaufender Knopf, Sprache aus dem Browser',
    substr_count($lsLp, '$datenschutz') >= 3 && str_contains($lsLp, 'name="werbung"') && !preg_match('~name="werbung"[^>]*required~', $lsLp)
    && str_contains($lsLp, 'name="von_partner"') && str_contains($lsLp, 'id="lp_leiste"') && str_contains($lsLp, 'Sprache::ausAnfrage(Sprache::ausBrowser(), $p[\'sprache\'] ?? null)')
    && str_contains((string) file_get_contents($wurzel . '/../zugang.php'), "Partner::ereignis((int) \$vp['id'], 'email')"));
pruefe('Partnerbereich: eigener Keks gegen eigene Aufrufe, Trichter mit Zeitraum',
    str_contains($tlPa = (string) file_get_contents($wurzel . '/../partner.php'), 'Partner::KEKS_SELBST') && str_contains($tlPa, 'Partner::trichter((int) $p[\'id\'], $zr)'));

/* ============================================================================
   62. Der erste Besuch: das Land stellt die Sprache   (27.09.2026)

   Uwe: "Stelle die Sprache automatisch ein, aus welchem Land er gerade in
   den Browser geht."

   Beim ersten Besuch entscheidet jetzt die Zeitzone des Geraets -- kein
   Geodienst, keine IP an Dritte, nichts, was die Datenschutzerklaerung
   Luegen straft. Danach nie wieder: Jede Wahl schlaegt die Vermutung, und
   wer einmal gewaehlt hat, wird nicht mehr umgeleitet.
   ============================================================================ */
abschnitt('62. Der erste Besuch: das Land stellt die Sprache');

$lbWurzel = dirname(__DIR__, 2);
$lbApp = (string) file_get_contents($lbWurzel . '/assets/js/app.js');

pruefe('die Zeitzone entscheidet, nicht ein fremder Geodienst',
    str_contains($lbApp, 'Intl.DateTimeFormat().resolvedOptions().timeZone')
    && !preg_match('~https?://[^"\']*(ipapi|ip-api|geoip|ipinfo|cloudflare\.com/cdn-cgi/trace)~i', $lbApp));
foreach (['europe/rome' => 'it', 'europe/berlin' => 'de', 'europe/vienna' => 'de',
          'europe/zurich' => 'de', 'europe/london' => 'en'] as $lbZone => $lbSpr) {
    pruefe('Zeitzone ' . $lbZone . ' fuehrt zu ' . $lbSpr,
        (bool) preg_match('~\'' . preg_quote($lbZone, '~') . '\':\s*\'' . $lbSpr . '\'~', $lbApp));
}
pruefe('ganze Erdteile ueber das Praefix (Amerika, Australien) fuehren zu Englisch',
    str_contains($lbApp, "'america/': 'en'") && str_contains($lbApp, "'australia/': 'en'"));
pruefe('eine unbekannte Zone leitet nicht um — auch UTC nicht, wie Suchroboter sie melden',
    str_contains($lbApp, 'return null;'));
pruefe('die Vermutung gilt nur, solange nichts gewaehlt wurde',
    str_contains($lbApp, 'if (!wunsch) {') && str_contains($lbApp, 'wunsch = landessprache();'));
pruefe('ein Klick auf den Umschalter macht daraus eine Entscheidung',
    str_contains($lbApp, 'autoLoeschen();   // ein Klick ist eine Entscheidung, keine Vermutung'));
pruefe('und der Sprachhinweis fragt bei einer Vermutung trotzdem noch',
    str_contains((string) file_get_contents($lbWurzel . '/assets/js/sprachhinweis.js'),
        "lesen('vecom-lang-auto') === '1'"));

/* ---------- Der Server hat keine Zeitzone, aber einen Sprachkopf -------- */
$lbAlt = $_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? null;
$lbKeks = $_COOKIE[Sprache::KEKS] ?? null;
unset($_COOKIE[Sprache::KEKS], $_REQUEST['lang']);

$_SERVER['HTTP_ACCEPT_LANGUAGE'] = 'de-AT,de;q=0.9,en;q=0.8';
pruefe('der Browserkopf wird gelesen (de-AT -> de)', Sprache::ausBrowser() === 'de');
$_SERVER['HTTP_ACCEPT_LANGUAGE'] = 'en;q=0.5,it;q=0.9';
pruefe('und die Gewichte werden geachtet (it vor en)', Sprache::ausBrowser() === 'it');
$_SERVER['HTTP_ACCEPT_LANGUAGE'] = 'ja,ko;q=0.8';
pruefe('was wir nicht sprechen, zaehlt nicht', Sprache::ausBrowser() === null);
$_SERVER['HTTP_ACCEPT_LANGUAGE'] = 'fr-FR,fr;q=0.9,en-GB;q=0.7';
pruefe('aus einer fremden Sprache mit englischem Zweitwunsch wird Englisch',
    Sprache::ausBrowser() === 'en');

$_SERVER['HTTP_ACCEPT_LANGUAGE'] = 'de-DE,de;q=0.9';
pruefe('ohne alles greift der Browserkopf', Sprache::ausAnfrage() === 'de');
pruefe('aber was an der Sache haengt, steht davor', Sprache::ausAnfrage('en') === 'en');
$_COOKIE[Sprache::KEKS] = 'it';
pruefe('und der Keks steht ueber beidem', Sprache::ausAnfrage('en') === 'it');
unset($_COOKIE[Sprache::KEKS]);
unset($_SERVER['HTTP_ACCEPT_LANGUAGE']);
pruefe('ganz ohne Hinweis bleibt es Italienisch', Sprache::ausAnfrage() === 'it');
if ($lbAlt !== null) { $_SERVER['HTTP_ACCEPT_LANGUAGE'] = $lbAlt; }
if ($lbKeks !== null) { $_COOKIE[Sprache::KEKS] = $lbKeks; }

/* ============================================================================
   63. Jede Seite folgt dem Land -- auch die, an die keiner denkt (27.09.2026)

   Uwe: "Wichtig, dass jede Unterseite alles in der jeweiligen Sprache
   ausgibt, anhand des Geraetestandortes."

   Die Weiche lag in app.js -- und die laedt nicht jede Seite. Showroom,
   Tischkonfigurator und die sieben Landeseiten blieben deshalb italienisch,
   egal woher jemand kam. Jetzt steht sie in assets/js/sprache.js, die jede
   gebaute Seite im Kopf traegt, und die Karte der Fassungen erzeugt
   build.mjs aus derselben Liste, aus der die Seiten entstehen.

   Diese Pruefung faellt auf, wenn eine neue Seite dazukommt und die Weiche
   vergessen wird -- der haeufigste Weg, wie so etwas zurueckkehrt.
   ============================================================================ */
abschnitt('63. Jede Seite folgt dem Land');

$jsWurzel = dirname(__DIR__, 2);

/* ---------- Die Karte kennt jede Seite in drei Sprachen ---------------- */
$jsKarte = $jsWurzel . '/assets/js/seiten.js';
pruefe('build.mjs hat die Seitenkarte geschrieben', is_file($jsKarte));
if (is_file($jsKarte)) {
    $jsRoh = (string) file_get_contents($jsKarte);
    $jsJson = trim(substr($jsRoh, (int) strpos($jsRoh, '{')));
    $jsJson = rtrim(rtrim($jsJson), ';');
    $jsSeiten = json_decode($jsJson, true);
    pruefe('sie ist lesbar und nicht leer', is_array($jsSeiten) && count($jsSeiten) >= 10,
        is_array($jsSeiten) ? (string) count($jsSeiten) : 'unlesbar');
    if (is_array($jsSeiten)) {
        $jsLuecken = [];
        foreach ($jsSeiten as $jsRolle => $jsFassungen) {
            foreach (['it', 'de', 'en'] as $jsSpr) {
                if (empty($jsFassungen[$jsSpr])) { $jsLuecken[] = $jsRolle . '/' . $jsSpr; }
            }
        }
        pruefe('jede Seite steht in allen drei Sprachen in der Karte',
            $jsLuecken === [], implode(' ', array_slice($jsLuecken, 0, 5)));
        pruefe('auch die Landeseiten stehen darin',
            isset($jsSeiten['siti-web-ristoranti']) && isset($jsSeiten['sito-o-booking']));
    }
}

/* ---------- Jede gebaute Seite laedt die Weiche ------------------------- */
$jsOhne = [];
foreach (['index.html', 'prezzi.html', 'assistenza.html', 'tecnica.html', 'tavolo.html',
          'siti-web-ristoranti.html', 'sito-o-booking.html',
          'de/index.html', 'de/preise.html', 'de/tisch.html', 'de/websites-restaurants.html',
          'en/index.html', 'en/table.html'] as $jsDatei) {
    $jsPfad = $jsWurzel . '/' . $jsDatei;
    if (!is_file($jsPfad)) { continue; }   // /de/ und /en/ entstehen erst beim Bauen
    $jsInhalt = (string) file_get_contents($jsPfad);
    if (!str_contains($jsInhalt, 'assets/js/sprache.js') || !str_contains($jsInhalt, 'assets/js/seiten.js')) {
        $jsOhne[] = $jsDatei;
    }
}
pruefe('jede gebaute Seite traegt die Weiche im Kopf', $jsOhne === [], implode(' ', $jsOhne));

/* ---------- Und jede Serverseite, auf der ein Fremder landen kann ------- */
/* Wer eine neue oeffentliche Seite baut, vergisst die zwei Zeilen leicht.
   Deshalb zaehlt hier nicht eine gepflegte Liste, sondern was im Ordner
   liegt: Jede PHP-Datei, die eine ganze Seite ausgibt, braucht beides. */
$jsAusnahmen = ['chef.php', 'werkstatt.php', 'cron.php', 'stripe-webhook.php', 'telefon.php',
                'formular.php', 'rueckruf.php', 'zahl.php', 'z.php', 'd.php', 'bezahlen.php',
                'domain-pruefung.php', 'pakete-daten.php', 'preise-daten.php', 'stimmen-daten.php',
                'akquise.php', 'config.local.example.php',
                // Demo-Vorschau eines Interessenten (01.10.2026): läuft in einer Sandbox ohne Skripte — die Weiche (ein Skript) liefe dort nicht
                'demo.php',
                // Weiterleitung der Telegram-Mini-App, zeigt selbst nichts; die Sprache kommt aus dem Knopf
                'telegram-app.php',
                // Das Vecom-Fenster in Telegram (01.10.2026): eigener schlichter Rahmen in Telegram, die Sprache kommt aus dem Kanal-Knopf
                'telegram-menue.php',
                // Claudes Erlaubnis-Tür (AI Office Stufe 2): Fehlerseite nur für Uwe, wenn Claude falsch fragt — deutsch, ohne Skript
                'claude-oauth.php', 'claude-mcp.php',
                // Exit-Paket (AI Office Stufe 5): liefert nur die Datei; die 410-Seite nimmt die Sprache aus ?lang, ohne Skript
                'exit-paket.php'];
$jsFehlt = [];
foreach (glob($jsWurzel . '/*.php') ?: [] as $jsPhp) {
    $jsName = basename($jsPhp);
    if (in_array($jsName, $jsAusnahmen, true)) { continue; }
    $jsInhalt = (string) file_get_contents($jsPhp);
    if (!preg_match('~<html\s+lang=~i', $jsInhalt)) { continue; }   // keine ganze Seite
    if (!str_contains($jsInhalt, 'Sprache::marken(') || !str_contains($jsInhalt, 'Sprache::skript()')) {
        $jsFehlt[] = $jsName;
    }
}
pruefe('jede oeffentliche Serverseite traegt Marke und Weiche',
    $jsFehlt === [], implode(' ', $jsFehlt));

/* ---------- Zwei Weichen waeren zwei Wahrheiten ------------------------- */
pruefe('app.js entscheidet nicht mehr selbst, wenn sprache.js da ist',
    str_contains((string) file_get_contents($jsWurzel . '/assets/js/app.js'),
        'if (VS) { return; }   // sprache.js hat das schon entschieden'));
pruefe('die Weiche leitet nur beim Einstieg von aussen um',
    str_contains((string) file_get_contents($jsWurzel . '/assets/js/sprache.js'), '!vonInnen()'));
pruefe('und auf Serverseiten nur bei einem gewoehnlichen Aufruf',
    str_contains((string) file_get_contents($jsWurzel . '/assets/js/sprache.js'), "data-lang-neu') === '1'")
    && str_contains((string) file_get_contents($jsWurzel . '/app/src/Sprache.php'), "=== 'GET'"));

abschnitt('Partner: Stripe-Konto im Land des Partners, Stand der Verifizierung');
/* 28.09.2026, Uwes Vorgabe: Land VOR dem Anlegen, als Stripe-„country“; Sprache
   bestimmt es nie; bestehende Konten werden nie automatisch verändert oder
   gelöscht; Stand über Abruf und Webhook account.updated. */
require_once $wurzel . '/src/Zahlung/Anbieter.php';
require_once $wurzel . '/src/Zahlung/Stripe.php';
$slNeu = static fn(string $n, string $sprache): array => Partner::laden(Partner::anlegen(['name' => $n, 'email' => strtolower(strtok($n, ' ')) . '@partner-sl.example', 'status' => 'aktiv', 'sprache' => $sprache]));
$slDe = $slNeu('Dieter Deutsch', 'de');
$slIt = $slNeu('Ida Italia', 'de');       // deutsche Oberfläche, lebt aber in Italien
$slAt = $slNeu('Anton Austria', 'it');    // italienische Oberfläche, lebt in Österreich
$slOhne = $slNeu('Olga Ohneland', 'de');
$slAuf = [];
$slKonto = static fn(string $weg, string $land, array $mehr = []): array => $mehr + ['id' => substr($weg, 13), 'country' => $land, 'details_submitted' => false,
    'charges_enabled' => false, 'payouts_enabled' => false, 'capabilities' => ['transfers' => 'inactive'],
    'requirements' => ['currently_due' => ['individual.verification.document', 'external_account'], 'past_due' => [], 'pending_verification' => []]];
$slStripeLand = [];          // acct → Land, wie Stripe es kennt
Partner::$stripeProbe = static function (string $m, string $weg, array $f, string $k) use (&$slAuf, &$slStripeLand, $slKonto): array {
    $slAuf[] = [$m, $weg, $f];
    if ($weg === '/v1/accounts' && $m === 'POST') {
        if (($f['country'] ?? '') === 'LI') { return ['error' => ['code' => 'country_unsupported', 'param' => 'country', 'message' => 'Country LI is not supported for this platform.']]; }
        if (($f['email'] ?? '') === 'panne@partner-sl.example') { return ['error' => ['message' => 'Internal error sk_live_ABCDEF123 req_1']]; }
        $id = 'acct_' . strtolower($f['country'] ?? 'xx') . count($slAuf); $slStripeLand[$id] = $f['country'] ?? 'IT';
        return ['id' => $id, 'country' => $slStripeLand[$id]];
    }
    if ($weg === '/v1/account_links') { return ['url' => 'https://connect.stripe.com/setup/x']; }
    if ($weg === '/v1/account_sessions') { return ['client_secret' => 'accs_secret_x']; }
    if ($m === 'DELETE') { return ['id' => substr($weg, 13), 'deleted' => true]; }
    if ($m === 'GET' && str_starts_with($weg, '/v1/accounts/')) { return $slKonto($weg, $slStripeLand[substr($weg, 13)] ?? 'IT'); }
    return ['error' => ['message' => '?']];
};

pruefe('Sprache bestimmt das Land nie: ohne Wahl kein Land (auch nicht bei deutscher Oberfläche)',
    Partner::landFuer($slDe) === '' && Partner::landFuer(['sprache' => 'de']) === '' && Partner::landFuer(['land' => 'at', 'sprache' => 'it']) === 'AT'
    && Partner::landFuer(['land' => 'XX', 'sprache' => 'en']) === '');
$slAuf = [];
$slR0 = Partner::stripeStarten($slOhne, null, 'link', 'https://pruefung.example/partner.php?t=o');
pruefe('Ohne gewähltes Land entsteht kein Stripe-Konto -- Stripe wird nicht einmal gefragt',
    !$slR0['ok'] && $slR0['grund'] === 'land' && $slAuf === [] && Partner::stripeGrundOeffentlich($slR0) === 'konto_land_fehlt'
    && Partner::createStripeConnectedAccount($slOhne)['grund'] === 'land');

$slAuf = [];
$slR = Partner::stripeStarten($slDe, 'DE', 'link', 'https://pruefung.example/partner.php?t=d');
$slPost = array_values(array_filter($slAuf, static fn($a) => $a[0] === 'POST' && $a[1] === '/v1/accounts'));
$slLink = array_values(array_filter($slAuf, static fn($a) => $a[1] === '/v1/account_links'));
$slDeN = Partner::laden((int) $slDe['id']);
pruefe('Neuer deutscher Partner: Konto mit country=DE, normales Konto (nicht „Empfänger“), Land und Stripe-Land gespeichert',
    $slR['ok'] && count($slPost) === 1 && ($slPost[0][2]['country'] ?? '') === 'DE' && !isset($slPost[0][2]['tos_acceptance[service_agreement]'])
    && $slDeN['land'] === 'DE' && $slDeN['stripe_land'] === 'DE' && $slDeN['stripe_onboarding_status'] === 'angelegt' && ($slPost[0][2]['metadata[partner_land]'] ?? '') === 'DE',
    json_encode($slPost[0][2] ?? []));
pruefe('Einrichtungslink: die bisherigen Rückwege bleiben (…&stripe=neu / …&stripe=zurueck)',
    ($slLink[0][2]['refresh_url'] ?? '') === 'https://pruefung.example/partner.php?t=d&stripe=neu'
    && ($slLink[0][2]['return_url'] ?? '') === 'https://pruefung.example/partner.php?t=d&stripe=zurueck');
$slAuf = [];
$slRi = Partner::stripeStarten($slIt, 'IT', 'sitzung');
pruefe('Neuer italienischer Partner (mit deutscher Oberfläche): country=IT und „Empfänger“-Konto, eingebettete Sitzung',
    $slRi['ok'] && ($slRi['secret'] ?? '') === 'accs_secret_x' && ($slAuf[0][2]['country'] ?? '') === 'IT'
    && ($slAuf[0][2]['tos_acceptance[service_agreement]'] ?? '') === 'recipient' && Partner::laden((int) $slIt['id'])['stripe_land'] === 'IT');
$slAuf = [];
Partner::stripeStarten($slAt, 'AT', 'link', 'https://pruefung.example/partner.php?t=a');
pruefe('Neuer österreichischer Partner (mit italienischer Oberfläche): country=AT',
    ($slAuf[0][2]['country'] ?? '') === 'AT' && Partner::laden((int) $slAt['id'])['stripe_land'] === 'AT');
$slAuf = [];
Partner::stripeStarten(Partner::laden((int) $slDe['id']), 'DE', 'link', 'https://pruefung.example/partner.php?t=d');
pruefe('Ein zweiter Klick legt kein zweites Konto an', !array_filter($slAuf, static fn($a) => $a[0] === 'POST' && $a[1] === '/v1/accounts'));

