    if ($m === 'getChatMember') {
        if ((int) $d['user_id'] === 9990001) { return ['ok' => true, 'result' => $kgRolle]; }
        return ['ok' => true, 'result' => ['status' => in_array((int) $d['user_id'], $kgTeam, true) ? 'administrator' : 'member']];
