    $w7N = basename($w7D);
    if (!isset($w7Routen[$w7N])) { continue; }
    $w7H = (string) @file_get_contents($w7D . '/.htaccess');
    if (!preg_match('~RewriteRule\s+\^\s+/app/index\.php~', $w7H)) { $w7Verdeckt[] = $w7N; }
}
