        [$qpW] = getimagesize($qpIm);
        $qpPruef("$qpF $qpS", $qpIm, $qpX['qr'], $qpW / (($qpL['b'] + 2 * $qpL['beschnitt']) * 10));
    }
}
foreach (array_keys(PartnerFlyer::liste()) as $qpS) {
