for ($i = 0; $i < PartnerLeads::NEU_JE_TAG; $i++) { Db::insert('partner_leads', ['partner_id' => $plBi, 'name' => 'Viel ' . $i, 'name_norm' => 'viel ' . $i, 'quelle' => 'eigen']); }
